  "inlineSchema": "// Match Point — Database Schema\n// Run: npx prisma migrate dev --name init\n// Requires DATABASE_URL in .env (Postgres recommended)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------------------------------------------------------------------------\n// Accounts & billing\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id               String   @id @default(uuid())\n  email            String   @unique\n  passwordHash     String\n  createdAt        DateTime @default(now())\n  stripeCustomerId String?  @unique\n\n  subscription Subscription?\n  purchases    PurchasedPick[]\n}\n\n// One active plan per user at a time. Single-pick buys don't create a row here —\n// they go straight into PurchasedPick. This table is for Daily/Weekly Bundle and\n// Monthly/Season Membership plans, which are recurring Stripe subscriptions.\nmodel Subscription {\n  id                   String   @id @default(uuid())\n  userId               String   @unique\n  user                 User     @relation(fields: [userId], references: [id])\n  stripeSubscriptionId String   @unique\n  plan                 String // \"daily_bundle\" | \"monthly_membership\" | \"weekly_bundle\" | \"season_membership\"\n  status               String // \"active\" | \"past_due\" | \"canceled\" | \"incomplete\"\n  currentPeriodEnd     DateTime\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n}\n\n// A single-pick purchase, or a record of a pick a subscriber is entitled to view.\nmodel PurchasedPick {\n  id          String   @id @default(uuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id])\n  pickId      String\n  pick        Pick     @relation(fields: [pickId], references: [id])\n  pricePaid   Int // cents\n  purchasedAt DateTime @default(now())\n\n  @@unique([userId, pickId])\n}\n\n// ---------------------------------------------------------------------------\n// Sports data\n// ---------------------------------------------------------------------------\n\nmodel Sport {\n  id      String  @id @default(uuid())\n  slug    String  @unique // \"tennis\" | \"basketball\" | \"soccer\" | \"baseball\" | \"football\"\n  name    String\n  matches Match[]\n}\n\nmodel Match {\n  id          String   @id @default(uuid())\n  sportId     String\n  sport       Sport    @relation(fields: [sportId], references: [id])\n  externalId  String   @unique // ID from the odds/data provider, for de-duping on each pull\n  league      String // \"ATP\" | \"NBA\" | \"EPL\" | \"MLB\" | \"NFL\" etc.\n  competitorA String\n  competitorB String\n  startTime   DateTime\n  status      String // \"scheduled\" | \"live\" | \"final\" | \"postponed\"\n  surface     String? // tennis only\n  venue       String?\n  liveScore   String? // free-text live score snapshot, updated by the live poller\n  liveClock   String? // \"Q3 8:42\", \"62'\", \"Top 6th\", \"Set 2\", etc.\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  picks Pick[]\n\n  @@index([sportId, startTime])\n}\n\n// ---------------------------------------------------------------------------\n// Model output\n// ---------------------------------------------------------------------------\n\nmodel Pick {\n  id         String   @id @default(uuid())\n  matchId    String\n  match      Match    @relation(fields: [matchId], references: [id])\n  pickType   String // \"model\" (has a real edge) | \"winner\" (a call on every match)\n  selection  String // \"Alvarez ML\", \"Home -4.5\", \"Over 8.5 Runs\" etc.\n  confidence Int // 0-100\n  odds       Int // American odds at time of pick\n  rationale  String // one-line qualitative note\n  isLive     Boolean  @default(false)\n  price      Int      @default(900) // cents, $9.00 default\n  createdAt  DateTime @default(now())\n\n  result    Result?\n  purchases PurchasedPick[]\n\n  @@index([matchId])\n}\n\nmodel Result {\n  id        String   @id @default(uuid())\n  pickId    String   @unique\n  pick      Pick     @relation(fields: [pickId], references: [id])\n  outcome   String // \"win\" | \"loss\" | \"push\"\n  settledAt DateTime @default(now())\n}\n",
